<script>
  import { onMount } from "svelte";
  import { get } from "../lib/api.js";
  import { siteName } from "../lib/preferences.js";
  let inventory = {}, docs = [], error = "", loading = true, search = "";
  const sections = [["hardware","Hosts"],["vms","VMs & runtimes"],["apps","Applications"],["storage","Storage"],["networks","Networks"]];
  onMount(async () => {
    try {
      const result = await Promise.all([...sections.map(([type]) => get(`/${type}`)), get("/docs")]);
      inventory = Object.fromEntries(sections.map(([type],i) => [type,result[i].data || []])); docs = result[5].data || [];
    } catch(e) { error = e.message; } finally { loading = false; }
  });
  $: hosts = inventory.hardware || [];
  $: results = search.trim() ? [...sections.flatMap(([type]) => (inventory[type]||[]).map(item => ({...item,type}))), ...docs.map(item => ({...item,name:item.title,type:"docs"}))].filter(item => `${item.name} ${item.hostname||""} ${item.ip_address||""}`.toLowerCase().includes(search.trim().toLowerCase())).slice(0,12) : [];
  $: recent = [...sections.flatMap(([type]) => (inventory[type]||[]).map(item => ({...item,type}))), ...docs.map(item => ({...item,name:item.title,type:"docs"}))].sort((a,b) => (b.updated_at||"").localeCompare(a.updated_at||"")).slice(0,6);
  const link = item => item.type === "docs" ? `#/docs/${item.id}` : `#/inventory/${item.type}/${item.id}`;
  function countApps(host) { const ids = new Set((inventory.vms||[]).filter(v=>v.hardware_id===host.id).map(v=>v.id)); return (inventory.apps||[]).filter(a=>a.hardware_id===host.id || ids.has(a.vm_id)).length; }
</script>
<section class="overview">
  <div class="eyebrow">YOUR INFRASTRUCTURE, REMEMBERED</div>
  <h1>{$siteName}</h1><p class="intro">Find a system, follow its connections, remember how it works.</p>
  {#if error}<p role="alert">Could not load the overview: {error}</p>{:else if loading}<p aria-live="polite">Loading your reference…</p>{:else}
  <label class="search-label">Find a host, application or document<input type="search" bind:value={search} placeholder="Search names, hostnames or IP addresses…" /></label>
  {#if search.trim()}<div class="search-results">{#each results as item}<a href={link(item)}><strong>{item.name}</strong><small>{item.type} · {item.ip_address||item.hostname||"Reference"}</small></a>{:else}<p>No matching records.</p>{/each}</div>{/if}
  <div class="stats">{#each sections as [type,label]}<a class="stat" href={`#/inventory/${type}`}><strong>{(inventory[type]||[]).length}</strong><span>{label}</span></a>{/each}<a class="stat" href="#/docs"><strong>{docs.length}</strong><span>Documents</span></a></div>
  <div class="section-heading"><div><h2>Your hosts</h2><p>Open a reference or explore one host at a time.</p></div><a href="#/inventory/hardware">Manage hosts →</a></div>
  <div class="host-grid">{#each hosts as host}<article class="host-card"><div class="host-mark">{#if host.icon?.startsWith("data:image/")}<img src={host.icon} alt="" />{:else}{host.icon || "▦"}{/if}</div><h3>{host.name}</h3><p>{host.os || "Operating system not recorded"}</p><code>{host.ip_address || host.hostname || "Address not recorded"}</code><div class="host-meta"><span>{countApps(host)} applications</span><span>{host.ram_gb ? `${host.ram_gb} GB RAM` : "RAM not recorded"}</span></div><div class="card-actions"><a href={`#/inventory/hardware/${host.id}`}>Open reference</a><a href={`#/map/hardware-${host.id}`}>Host map →</a></div></article>{:else}<article class="host-card"><h3>Start with a host</h3><p>Add your first server or import your existing inventory.</p><a href="#/inventory/hardware">Open hardware inventory →</a></article>{/each}</div>
  <div class="bottom-grid"><article><h2>Recently changed</h2><p class="subtle">Record edits, not live system events.</p>{#each recent as item}<a class="recent" href={link(item)}><span>{item.name}<small>{item.type}</small></span><small>{item.updated_at?.slice(0,10)||"Undated"}</small></a>{:else}<p>No records yet.</p>{/each}</article><article class="reference-card"><div class="eyebrow">LEAVE YOURSELF A TRAIL</div><h2>Make the next visit easier.</h2><p>Keep the purpose, configuration paths, maintenance commands and previous fixes alongside each system.</p><a href="#/docs">Browse documentation →</a><hr/><p class="subtle">Inventory information is recorded data. Counts and timestamps do not imply a live health check.</p></article></div>
  {/if}
</section>
<style>
.overview{max-width:1280px;margin:auto}.eyebrow{color:var(--pico-primary);font-size:.72rem;font-weight:750;letter-spacing:.13em}.overview h1{font-size:2.5rem;letter-spacing:-.05em;margin:.4rem 0}.intro{color:var(--pico-muted-color);margin-bottom:1.8rem}.search-label{font-size:.8rem;max-width:700px}.search-label input{margin-top:.5rem}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:1rem;margin:1rem 0 2rem}.stat{padding:1.1rem;border:1px solid var(--pico-muted-border-color);border-radius:12px;background:var(--pico-card-background-color);text-decoration:none;display:flex;flex-direction:column;gap:.2rem}.stat strong{font-size:1.7rem;color:var(--pico-color)}.stat span{font-size:.75rem;color:var(--pico-muted-color)}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem}.section-heading h2,.bottom-grid h2{font-size:1.25rem;margin:0}.section-heading p{font-size:.8rem;color:var(--pico-muted-color);margin:.3rem 0 1rem}.section-heading>a{font-size:.8rem}.host-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem}.host-card{margin:0;padding:1.3rem;border-radius:14px;border:1px solid var(--pico-muted-border-color);box-shadow:none}.host-mark{width:48px;height:48px;display:grid;place-items:center;background:var(--hlh-tint);border-radius:12px;font-size:1.6rem;margin-bottom:1rem}.host-mark img{max-width:34px;max-height:34px}.host-card h3{font-size:1.2rem;margin:0 0 .25rem}.host-card p{font-size:.85rem;color:var(--pico-muted-color);margin-bottom:.6rem}.host-card code{font-size:.8rem}.host-meta{display:flex;gap:1rem;font-size:.75rem;color:var(--pico-muted-color);padding:1rem 0}.card-actions{display:flex;justify-content:space-between;border-top:1px solid var(--pico-muted-border-color);padding-top:1rem;font-size:.8rem}.bottom-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:1rem;margin-top:1.5rem}.bottom-grid article{box-shadow:none;border:1px solid var(--pico-muted-border-color);border-radius:14px;padding:1.3rem}.subtle{font-size:.8rem;color:var(--pico-muted-color)}.recent{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:.65rem 0;border-bottom:1px solid var(--pico-muted-border-color);text-decoration:none;font-size:.85rem}.recent small{display:block;color:var(--pico-muted-color);font-size:.7rem}.reference-card{background:var(--hlh-tint)}.reference-card h2{margin:.8rem 0}.reference-card>p{font-size:.9rem}.search-results{border:1px solid var(--pico-muted-border-color);padding:.5rem 1rem;border-radius:10px;margin-bottom:1rem}.search-results a{display:flex;justify-content:space-between;gap:1rem;padding:.6rem 0;text-decoration:none}.search-results small{color:var(--pico-muted-color)}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.stats{grid-template-columns:repeat(2,1fr)}.bottom-grid{grid-template-columns:1fr}.section-heading{align-items:start}.overview h1{font-size:2rem}}
</style>